return items.map(item => {
  const r = item.json;
  return {
    json: {
      source: 'usaspending',
      source_id: String(r['Award ID'] || ''),
      title: (r['Description'] || '').slice(0, 500),
      naics: '236220',
      state: r['Place of Performance State Code'] || null,
      value: r['Award Amount'] ? Number(r['Award Amount']) : null,
      posted_at: r['Start Date'] || null,
      deadline: r['End Date'] || null,
      raw: r
    }
  };
});
